// lib/poll.js - one guarded interval for the whole app.
//
// Idle tabs polled unconditionally: four separate setInterval call sites with no
// visibility check, so a backgrounded tab kept hitting the API indefinitely.
export function useVisiblePoll(fn, ms) {
  useEffect(() => {
    let id = null;
    const tick = () => { if (!document.hidden) fn(); };
    const start = () => { if (id === null) { id = setInterval(tick, ms); tick(); } };
    const stop = () => { if (id !== null) { clearInterval(id); id = null; } };
    const onVis = () => (document.hidden ? stop() : start());
    document.addEventListener('visibilitychange', onVis);
    start();
    return () => { stop(); document.removeEventListener('visibilitychange', onVis); };
  }, [fn, ms]);
}

